-- Additive migration. Preserve all historical plan rows, subscriptions and paid orders.
ALTER TABLE credit_wallets ADD COLUMN plan_balance DECIMAL(12,2) NOT NULL DEFAULT 0;
ALTER TABLE credit_wallets ADD COLUMN plan_period_key TEXT;
CREATE TABLE plan_stored_files (
 id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, path TEXT NOT NULL UNIQUE,
 size_bytes BIGINT NOT NULL CHECK (size_bytes >= 0), created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX plan_stored_files_organization_id_idx ON plan_stored_files(organization_id);
CREATE TABLE plan_usage (
 id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, resource TEXT NOT NULL,
 reference_id TEXT NOT NULL, period_key TEXT NOT NULL, amount INTEGER NOT NULL,
 created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CONSTRAINT plan_usage_positive CHECK (amount > 0)
);
CREATE UNIQUE INDEX plan_usage_organization_id_resource_reference_id_key ON plan_usage(organization_id,resource,reference_id);
CREATE INDEX plan_usage_organization_id_resource_period_key_idx ON plan_usage(organization_id,resource,period_key);
UPDATE subscription_plans SET is_active=false WHERE code IN ('starter','msp-pro-1m','msp-pro-6m','msp-pro-12m');
